insert into public.blogs (id, title, excerpt, author, author_avatar, category, tags, read_time, publish_date, source_name, url, cover_image, cover_alt, cover_fit, status, featured)
values
('sander-dieleman-noise-schedules-considered-harmful', 'Noise schedules considered harmful', 'Sander Dieleman argues that the noise schedule is a superfluous abstraction in diffusion models that entangles time reparameterization, loss weighting, and sampling behavior, and shows how reasoning directly in terms of signal-to-noise ratio disentangles these design choices.', 'Sander Dieleman', 'https://www.google.com/s2/favicons?domain=sander.ai&sz=128', 'Visual Generation', array['Diffusion Models','Noise Schedules','Loss Weighting','Generative Modeling'], '22 min read', '2024-06-14', 'Sander Dieleman', 'https://sander.ai/2024/06/14/noise-schedules.html', 'assets/img/covers/real/sander-dieleman-noise-schedules-considered-harmful.jpg', 'Real cover from twitter:image', 'cover', 'published', false),
('sander-dieleman-paradox-of-diffusion-distillation', 'The paradox of diffusion distillation', 'Sander Dieleman examines the tension at the heart of diffusion distillation: iterative refinement is what makes diffusion models work, yet distillation methods keep trying to make sampling less iterative, and he maps the trade-offs across consistency models, adversarial approaches, and progressive distillation.', 'Sander Dieleman', 'https://www.google.com/s2/favicons?domain=sander.ai&sz=128', 'Visual Generation', array['Diffusion Models','Distillation','Sampling Efficiency','Consistency Models'], '25 min read', '2024-02-28', 'Sander Dieleman', 'https://sander.ai/2024/02/28/paradox.html', 'assets/img/covers/real/sander-dieleman-paradox-of-diffusion-distillation.jpg', 'Real cover from twitter:image', 'cover', 'published', false),
('nvidia-autoregressive-video-generation', 'Autoregressive Video Generation', 'NVIDIA''s Efficient AI lab surveys autoregressive video generation, explaining why causal structure enables streaming inference and KV-cache reuse, how few-step distillation makes block-wise generation practical, and how recent systems extend video length while cutting training cost.', 'Song Han', 'https://www.google.com/s2/favicons?domain=research.nvidia.com&sz=128', 'Visual Generation', array['Video Generation','Autoregressive Models','KV Cache','Distillation'], '14 min read', '2026-07-13', 'NVIDIA Research', 'https://research.nvidia.com/labs/eai/blogs/autoregressive-video-gen/', 'assets/img/covers/real/nvidia-autoregressive-video-generation.svg', 'Article figure comparing full-sequence diffusion with autoregressive diffusion', 'cover', 'published', false),
('meta-muse-image-and-muse-video', 'Introducing Muse Image and Muse Video', 'Meta Superintelligence Labs details its first media generation models: Muse Image treats image generation as an agentic process that invokes search and code tools and self-refines with test-time compute, while Muse Video builds on the same pretraining base to add native audio support.', 'Meta Superintelligence Labs', 'https://www.google.com/s2/favicons?domain=ai.meta.com&sz=128', 'Visual Generation', array['Image Generation','Video Generation','Agentic Tool Use','Test-Time Compute'], '15 min read', '2026-07-07', 'Meta AI', 'https://ai.meta.com/blog/introducing-muse-image-muse-video-msl/', 'assets/img/covers/real/meta-muse-image-and-muse-video.webp', 'Real cover from og:image', 'cover', 'published', false),
('nvidia-video-generation-infrastructure-problem', 'Why Video Generation Is an Infrastructure Problem', 'NVIDIA''s Efficient AI lab argues that scaling video generation is now dominated by systems concerns, walking through long-context attention, memory budgets, decoding, scheduling, compression, and parallelism, and showing how deployment-aware design decisions shape model architecture.', 'Song Han', 'https://www.google.com/s2/favicons?domain=research.nvidia.com&sz=128', 'Visual Generation', array['Video Generation','Inference Systems','Parallelism','Long Context'], '13 min read', '2026-05-26', 'NVIDIA Research', 'https://research.nvidia.com/labs/eai/blogs/video-gen-is-an-infra-problem/', 'assets/img/covers/real/nvidia-video-generation-infrastructure-problem.png', 'Article figure on video generation infrastructure', 'cover', 'published', false),
('diffusionflow-diffusion-meets-flow-matching', 'Diffusion Meets Flow Matching: Two Sides of the Same Coin', 'Ruiqi Gao and colleagues at Google DeepMind show that Gaussian flow matching and diffusion models are mathematically equivalent under a unified parameterization, using interactive figures to connect training objectives, weighting functions, ODE and SDE samplers, and noise schedules across both frameworks.', 'Ruiqi Gao, Emiel Hoogeboom, Jonathan Heek, et al.', 'https://www.google.com/s2/favicons?domain=diffusionflow.github.io&sz=128', 'Visual Generation', array['Flow Matching','Diffusion Models','ODE Samplers','Generative Modeling'], '20 min read', '2024-12-02', 'diffusionflow.github.io', 'https://diffusionflow.github.io/', 'assets/img/covers/real/diffusionflow-diffusion-meets-flow-matching.gif', 'Animated article figure showing particle movement between distributions', 'cover', 'published', false),
('meta-fair-partnr-human-robot-collaboration', 'Advancing machine intelligence through human-centered research', 'Meta FAIR introduces PARTNR, a 100,000-task benchmark, dataset, and planning model for human-robot collaboration built on Habitat 3.0, showing that state-of-the-art LLM planners still fail at coordination and error recovery while a fine-tuned smaller planner runs 8.6x faster and makes human partners 24% more efficient.', 'Meta FAIR', 'https://www.google.com/s2/favicons?domain=ai.meta.com&sz=128', 'World Model', array['Human-Robot Collaboration','Embodied AI','Benchmarks','Habitat','Planning'], '12 min read', '2025-02-07', 'Meta AI', 'https://ai.meta.com/blog/machine-intelligence-research-new-models/', 'assets/img/covers/real/meta-fair-partnr-human-robot-collaboration.jpg', 'Real cover from og:image', 'cover', 'published', false),
('bair-rl-traffic-smoothing-100-av-deployment', 'Scaling Up Reinforcement Learning for Traffic Smoothing: A 100-AV Highway Deployment', 'Berkeley researchers describe training RL controllers in fast data-driven simulation and deploying them on 100 autonomous vehicles on Nashville''s I-24, where the controllers dampened stop-and-go traffic waves and cut fuel consumption for surrounding human drivers by up to 20 percent.', 'Nathan Lichtlé, Kathy Jang, Eugene Vinitsky, et al.', 'https://www.google.com/s2/favicons?domain=bair.berkeley.edu&sz=128', 'World Model', array['Reinforcement Learning','Autonomous Vehicles','Sim-to-Real','Field Deployment'], '9 min read', '2025-03-25', 'BAIR Blog', 'https://bair.berkeley.edu/blog/2025/03/25/rl-av-smoothing/', 'assets/img/covers/real/bair-rl-traffic-smoothing-100-av-deployment.png', 'Real cover from og:image', 'cover', 'published', false),
('ai2-molmospaces-embodied-ai-ecosystem', 'MolmoSpaces, an open ecosystem for embodied AI', 'Ai2 presents MolmoSpaces, an open platform of physics-grounded scenes, objects, and grasp annotations for training and evaluating generalist robotic policies, positioning reproducible simulation assets as shared infrastructure for embodied AI research.', 'Ai2', 'https://www.google.com/s2/favicons?domain=allenai.org&sz=128', 'World Model', array['Embodied AI','Robotics','Simulation','Open Source'], '8 min read', '2026-02-11', 'Ai2 Blog', 'https://allenai.org/blog/molmospaces', 'assets/img/covers/real/ai2-molmospaces-embodied-ai-ecosystem.jpg', 'Real cover from og:image', 'cover', 'published', false),
('google-deepmind-gemini-robotics-1-5', 'Gemini Robotics 1.5 brings AI agents into the physical world', 'Google DeepMind explains the two-model design behind Gemini Robotics 1.5: an embodied reasoning model that plans, thinks, and calls tools, paired with a vision-language-action model that transfers learned motions across different robot embodiments to execute multi-step physical tasks.', 'Carolina Parada', 'https://www.google.com/s2/favicons?domain=deepmind.google&sz=128', 'World Model', array['Robotics','Vision-Language-Action','Embodied Reasoning','Cross-Embodiment'], '10 min read', '2025-09-25', 'Google DeepMind', 'https://deepmind.google/discover/blog/gemini-robotics-15-brings-ai-agents-into-the-physical-world/', 'assets/img/covers/real/google-deepmind-gemini-robotics-1-5.webp', 'Real cover from og:image', 'cover', 'published', false),
('arena-agent-arena-causal-evaluation', 'Agent Arena: Causal Evaluation of Agents in the Real World', 'Arena describes a causal evaluation methodology for AI agents grounded in real user interactions, using randomized assignment to isolate the effect of the orchestrator from the underlying model so agent rankings scale with actual usage instead of static benchmarks.', 'Arena Team', 'https://www.google.com/s2/favicons?domain=arena.ai&sz=128', 'AI Agents', array['Agent Evaluation','Causal Inference','Real-World Tasks','Methodology'], '11 min read', '2026-06-04', 'Arena.ai', 'https://arena.ai/blog/agent-arena-methodology', 'assets/img/covers/real/arena-agent-arena-causal-evaluation.png', 'Real cover from og:image', 'cover', 'published', false),
('github-copilot-agentic-harness-evaluation', 'Evaluating performance and efficiency of the GitHub Copilot agentic harness across models and tasks', 'GitHub benchmarks its Copilot agentic harness against other coding harnesses under fixed models, tasks, and budgets, reporting resolution rate alongside token consumption, cost, and wall-clock time to argue that harness design, not just model choice, drives agentic coding outcomes.', 'Shibani Basava, Carlos Castro', 'https://www.google.com/s2/favicons?domain=github.blog&sz=128', 'AI Agents', array['Coding Agents','Agent Harness','Benchmarks','Token Efficiency'], '12 min read', '2026-06-25', 'The GitHub Blog', 'https://github.blog/ai-and-ml/github-copilot/evaluating-performance-and-efficiency-of-the-github-copilot-agentic-harness-across-models-and-tasks/', 'assets/img/covers/real/github-copilot-agentic-harness-evaluation.png', 'Article figure showing the Copilot agentic harness architecture across surfaces', 'cover', 'published', false),
('letta-context-repositories-git-memory', 'Introducing Context Repositories: Git-based Memory for Coding Agents', 'Letta rebuilds coding-agent memory around Git: context is stored as versioned files with frontmatter metadata, edited by a memory subagent in an isolated worktree, giving agents auditable, diffable long-term memory instead of opaque vector stores.', 'Letta', 'https://www.google.com/s2/favicons?domain=letta.com&sz=128', 'AI Agents', array['Agent Memory','Context Management','Coding Agents','Git'], '9 min read', '2026-02-12', 'Letta Blog', 'https://www.letta.com/blog/context-repositories/', 'assets/img/covers/real/letta-context-repositories-git-memory.png', 'Real cover from og:image', 'cover', 'published', false),
('hf-is-it-agentic-enough', 'Is it agentic enough? Benchmarking open models on your own tooling', 'Hugging Face maintainers run controlled experiments benchmarking open models against their own agentic tooling, showing how to measure tool-calling reliability and task completion on the harness you actually use rather than trusting leaderboard numbers.', 'Ben Burtenshaw, Merve Noyan, Pedro Cuenca, et al.', 'https://www.google.com/s2/favicons?domain=huggingface.co&sz=128', 'AI Agents', array['Agent Evaluation','Open Models','Tool Calling','Benchmarks'], '10 min read', '2026-06-18', 'Hugging Face Blog', 'https://huggingface.co/blog/is-it-agentic-enough', 'assets/img/covers/real/hf-is-it-agentic-enough.png', 'Real cover from og:image', 'cover', 'published', false),
('msr-magentic-ui-human-centered-web-agent', 'Magentic-UI, an experimental human-centered web agent', 'Microsoft Research presents Magentic-UI, an open-source web agent built around human oversight: co-planning, action approvals, answer verification, and plan memory let people steer browser-based tasks while the system studies where human-in-the-loop control actually improves agent safety and reliability.', 'Microsoft Research', 'https://www.google.com/s2/favicons?domain=microsoft.com&sz=128', 'AI Agents', array['Web Agents','Human-in-the-Loop','Agent Safety','Open Source'], '11 min read', '2025-05-19', 'Microsoft Research Blog', 'https://www.microsoft.com/en-us/research/blog/magentic-ui-an-experimental-human-centered-web-agent/', 'assets/img/covers/real/msr-magentic-ui-human-centered-web-agent.jpg', 'Real cover from og:image', 'cover', 'published', false),
('msr-magentic-one-generalist-multi-agent', 'Magentic-One: A Generalist Multi-Agent System for Solving Complex Tasks', 'Microsoft Research details Magentic-One, a multi-agent architecture where an Orchestrator maintains task and progress ledgers while delegating to specialized web-browsing, file-navigation, and coding agents, achieving competitive results on GAIA, AssistantBench, and WebArena without modifying the underlying models.', 'Adam Fourney, Gagan Bansal, Hussein Mozannar, et al.', 'https://www.google.com/s2/favicons?domain=microsoft.com&sz=128', 'AI Agents', array['Multi-Agent Systems','Orchestration','Agent Benchmarks','AutoGen'], '14 min read', '2024-11-04', 'Microsoft Research Blog', 'https://www.microsoft.com/en-us/research/articles/magentic-one-a-generalist-multi-agent-system-for-solving-complex-tasks/', 'assets/img/covers/real/msr-magentic-one-generalist-multi-agent.png', 'Real cover from og:image', 'cover', 'published', false),
('metr-task-standard-portable-evaluation-tasks', 'Portable Evaluation Tasks via the METR Task Standard', 'METR publishes a standard format for defining agent evaluation tasks so the same task definition, environment setup, and scoring logic can run unchanged across different evaluation harnesses, reducing duplicated engineering and making dangerous-capability evaluations easier to share between labs.', 'METR', 'https://www.google.com/s2/favicons?domain=metr.org&sz=128', 'AI Agents', array['Agent Evaluation','Task Standard','Interoperability','Evals Infrastructure'], '6 min read', '2024-02-29', 'METR Blog', 'https://metr.org/blog/2024-02-29-metr-task-standard/', 'assets/img/covers/real/metr-task-standard-portable-evaluation-tasks.svg', 'Editorial diagram of one task standard running across multiple evaluation harnesses', 'cover', 'published', false),
('metr-expenditure-horizon', 'Expenditure Horizon: Measuring Optimization Ability, with an Application to NanoGPT', 'METR proposes the expenditure horizon, a metric that measures an agent''s optimization ability by how much human-equivalent spending its improvements match, and illustrates the measure empirically on the NanoGPT speedrun to track how agents compare to human optimization effort over time.', 'METR', 'https://www.google.com/s2/favicons?domain=metr.org&sz=128', 'AI Agents', array['Agent Evaluation','Optimization','NanoGPT','Capability Measurement'], '10 min read', '2026-07-21', 'METR Blog', 'https://metr.org/blog/2026-07-21-expenditure-horizon/', 'assets/img/covers/real/metr-expenditure-horizon.svg', 'Real cover from og:image', 'cover', 'published', false),
('bair-compound-ai-systems', 'The Shift from Models to Compound AI Systems', 'Matei Zaharia and colleagues argue that state-of-the-art AI results increasingly come from compound systems that combine multiple model calls, retrievers, and external tools rather than single models, and analyze the design and optimization questions this shift raises for builders.', 'Matei Zaharia, Omar Khattab, Lingjiao Chen, et al.', 'https://www.google.com/s2/favicons?domain=bair.berkeley.edu&sz=128', 'AI Agents', array['Compound AI Systems','System Design','Retrieval','LLM Applications'], '12 min read', '2024-02-18', 'BAIR Blog', 'https://bair.berkeley.edu/blog/2024/02/18/compound-ai-systems/', 'assets/img/covers/real/bair-compound-ai-systems.png', 'Real cover from og:image', 'cover', 'published', false),
('google-few-shot-tool-use-doesnt-work-yet', 'Few-shot tool-use doesn''t really work (yet)', 'Alon Jacovi reports a large-scale comparison of tool-assisted generation strategies, finding that few-shot tool calling generally fails to beat no-tool baselines on question answering and reasoning tasks, and diagnoses why demonstrations alone are insufficient for reliable tool use.', 'Alon Jacovi', 'https://www.google.com/s2/favicons?domain=research.google&sz=128', 'AI Agents', array['Tool Use','Few-Shot Learning','Negative Results','Evaluation'], '8 min read', '2024-05-30', 'Google Research Blog', 'https://research.google/blog/few-shot-tool-use-doesnt-really-work-yet/', 'assets/img/covers/real/google-few-shot-tool-use-doesnt-work-yet.jpg', 'Real cover from og:image', 'cover', 'published', false),
('msr-plugmem-reusable-agent-memory', 'PlugMem: Transforming raw agent interactions into reusable knowledge', 'Microsoft Research introduces PlugMem, a memory system that converts raw agent interaction histories into a structured knowledge graph of facts and skills, demonstrating cross-task memory reuse on three task families while significantly reducing memory token consumption.', 'Microsoft Research', 'https://www.google.com/s2/favicons?domain=microsoft.com&sz=128', 'AI Agents', array['Agent Memory','Knowledge Graphs','Skill Reuse','Token Efficiency'], '10 min read', '2026-03-10', 'Microsoft Research Blog', 'https://www.microsoft.com/en-us/research/blog/from-raw-interaction-to-reusable-knowledge-rethinking-memory-for-ai-agents/', 'assets/img/covers/real/msr-plugmem-reusable-agent-memory.jpg', 'Real cover from og:image', 'cover', 'published', false),
('hazyresearch-minions-to-openjarvis-retrospective', 'From Minions to OpenJarvis: A Retrospective on Two Years in Local AI', 'Jon Saad-Falcon and Avanika Narayan look back on two years of building local-cloud agent systems at Hazy Research, tracing how the Minions cost-accuracy trade-off evolved into the OpenJarvis personal agent stack and distilling lessons about where small on-device models genuinely hold up.', 'Jon Saad-Falcon, Avanika Narayan', 'https://www.google.com/s2/favicons?domain=hazyresearch.stanford.edu&sz=128', 'AI Agents', array['Local Models','Personal Agents','Cost-Accuracy Trade-offs','Systems Retrospective'], '15 min read', '2026-05-15', 'Hazy Research', 'https://hazyresearch.stanford.edu/blog/2026-05-15-minions-to-openjarvis-retrospective', 'assets/img/covers/real/hazyresearch-minions-to-openjarvis-retrospective.png', 'Article hero figure from the OpenJarvis retrospective', 'cover', 'published', false),
('ai2-evaluating-scientific-discovery-agents', 'Evaluating agents for scientific discovery', 'Ai2 uses its ScienceWorld and DiscoveryWorld benchmarks to test whether AI agents can run the full scientific loop of hypothesizing, experimenting, and concluding, finding that even strong agents struggle with discovery problems human scientists solve routinely.', 'Ai2', 'https://www.google.com/s2/favicons?domain=allenai.org&sz=128', 'AI Agents', array['Scientific Discovery','Agent Benchmarks','ScienceWorld','Evaluation'], '9 min read', '2026-04-13', 'Ai2 Blog', 'https://allenai.org/blog/evaluating-scientific-discovery-agents', 'assets/img/covers/real/ai2-evaluating-scientific-discovery-agents.jpg', 'Real cover from og:image', 'cover', 'published', false)
